const normalize = (value) => value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')

const makeEntry = (word, definition, simple, type = 'Mot') => ({
  word,
  type,
  definition,
  simple: simple || definition,
  synonyms: [],
  antonyms: [],
  example: `Exemple : « ${word} » est un mot que l’on peut utiliser dans une phrase.`,
  level: 'Facile',
})

const reasoningEntries = reasoningWords.map(([word, type, definition, simple]) => makeEntry(word, definition, simple, type))
const vocabularyEntries = Object.entries(words).map(([word, definition]) => makeEntry(word, definition))

export const dictionary = [...reasoningEntries, ...vocabularyEntries].filter((item, index, list) => list.findIndex((other) => normalize(other.word) === normalize(item.word)) === index)

export { normalize }
